contracts/AuditStorage.sol.content:
pragma solidity ^0.8.0;

contract AuditStorage {
    struct AuditRecord {
        uint256 timestamp;
        address submitter;
        string operationType;
        string userId;
    }

    mapping(string => AuditRecord) public records;
    string[] public recordIndex;

    event AuditStored(string hashValue, uint256 timestamp, string operationType, string userId);

    function storeAuditHash(string memory hashValue, uint256 timestamp, string memory operationType, string memory userId) public returns (bool) {
        require(records[hashValue].timestamp == 0, "Hash already exists");
        records[hashValue] = AuditRecord(timestamp, msg.sender, operationType, userId);
        recordIndex.push(hashValue);
        emit AuditStored(hashValue, timestamp, operationType, userId);
        return true;
    }

    function getTotalRecords() public view returns (uint256) {
        return recordIndex.length;
    }

    function getRecordByHash(string memory hashValue) public view returns (
        uint256 timestamp,
        address submitter,
        string memory operationType,
        string memory userId
    ) {
        AuditRecord memory r = records[hashValue];
        require(r.timestamp != 0, "Record not found");
        return (r.timestamp, r.submitter, r.operationType, r.userId);
    }

    function getRecordByIndex(uint256 index) public view returns (
        string memory hashValue,
        uint256 timestamp,
        address submitter,
        string memory operationType,
        string memory userId
    ) {
        require(index < recordIndex.length, "Index out of bounds");
        string memory key = recordIndex[index];
        AuditRecord memory r = records[key];
        return (key, r.timestamp, r.submitter, r.operationType, r.userId);
    }
}

contracts/UserRegistry.sol.content:
pragma solidity ^0.8.0;

contract UserRegistry {
    struct UserRecord {
        string pkHash;
        uint256 createdAt;
        uint256 updatedAt;
        bool exists;
    }

    mapping(address => UserRecord) private users;
    address[] public userIndex;

    event UserRegistered(address indexed usr, string pkHash, uint256 time);
    event UserUpdated(address indexed usr, string oldHash, string newHash, uint256 time);

    function register(string memory pkHash) public {
        require(!users[msg.sender].exists, "Already registered, use update");
        users[msg.sender] = UserRecord(pkHash, block.timestamp, block.timestamp, true);
        userIndex.push(msg.sender);
        emit UserRegistered(msg.sender, pkHash, block.timestamp);
    }

    function update(string memory newPkHash) public {
        require(users[msg.sender].exists, "Not registered yet");
        string memory oldHash = users[msg.sender].pkHash;
        users[msg.sender].pkHash = newPkHash;
        users[msg.sender].updatedAt = block.timestamp;
        emit UserUpdated(msg.sender, oldHash, newPkHash, block.timestamp);
    }

    function getUser(address usr) public view returns (
        string memory pkHash,
        uint256 createdAt,
        uint256 updatedAt
    ) {
        UserRecord memory u = users[usr];
        require(u.exists, "Not found");
        return (u.pkHash, u.createdAt, u.updatedAt);
    }

    function getTotalUsers() public view returns (uint256) {
        return userIndex.length;
    }
}

contracts/ZKPVerifier.sol.content:
pragma solidity ^0.8.0;

contract ZKPVerifier {
    struct ProofResult {
        bool valid;
        uint256 timestamp;
        address submitter;
        string proofHash;
    }

    mapping(bytes32 => ProofResult) public verifiedProofs;

    event ProofVerified(bytes32 indexed proofId, bool valid, uint256 timestamp);

    function recordProofResult(bytes32 proofId, bool valid, string memory proofHash) public returns (bool) {
        require(verifiedProofs[proofId].timestamp == 0, "Proof already recorded");
        verifiedProofs[proofId] = ProofResult(valid, block.timestamp, msg.sender, proofHash);
        emit ProofVerified(proofId, valid, block.timestamp);
        return true;
    }

    function getProofResult(bytes32 proofId) public view returns (bool, uint256, address, string memory) {
        ProofResult memory r = verifiedProofs[proofId];
        require(r.timestamp != 0, "Proof not found");
        return (r.valid, r.timestamp, r.submitter, r.proofHash);
    }
}

